/**
 * The canvas writes schema edits back into the artifact, so these functions are
 * the difference between "the analyst's change is saved" and "the agent's file
 * got rewritten and lost its comments, index names and defaults". The fixture is
 * the shape real ERD artifacts have (see output/erd/*.md in a project).
 */
import { expect, test } from "bun:test";
import { setColumnRef, addTableToDbml, removeTableFromDbml, updateTableInDbml } from "~/lib/dbml-edit";
import { parseDbml } from "~/lib/dbml";

const SOURCE = `// TechnoDay schema
// Generated by FSD Analyzer

Table nominations_current as nominations {
  id uuid [pk, default: \`gen_random_uuid()\`]
  nama_pengirim varchar(100) [not null, note: "Check char_length <= 100"]
  created_at timestamptz [not null, default: \`now()\`, note: "Index DESC"]

  indexes {
    created_at [name: "idx_nominations_created_at"]
  }
}

Table divisions {
  id uuid [pk, default: \`gen_random_uuid()\`]
  code varchar(50) [unique, not null]
}

Table employees {
  id uuid [pk, default: \`gen_random_uuid()\`]
  division_id uuid [ref: > divisions.id]
  // someone's note about a column
  is_active boolean [default: true]
}

Ref: employees.id > nominations_current.id
`;

test("drawing a relation replaces the column's existing inline ref, appending nothing", () => {
  // `division_id` already has `ref: > divisions.id`; the drag points it at `code`.
  const out = setColumnRef(SOURCE, { from: { table: "employees", column: "division_id" }, to: { table: "divisions", column: "code" } });
  const employees = parseDbml(out).tables.find((t) => t.name === "employees")!;
  expect(employees.columns.find((c) => c.name === "division_id")!.ref).toEqual({ table: "divisions", column: "code", relation: ">" });
  expect(out).not.toContain("ref: > divisions.id");
  expect(out.match(/Ref:/g)!.length).toBe(1); // the pre-existing standalone ref only
  // The comments, the index name and the backtick default survive.
  expect(out).toContain("// TechnoDay schema");
  expect(out).toContain('created_at [name: "idx_nominations_created_at"]');
  expect(out).toContain("default: `gen_random_uuid()`");
});

test("drawing a relation from a column without a ref appends one Ref line", () => {
  const out = setColumnRef(SOURCE, { from: { table: "employees", column: "is_active" }, to: { table: "divisions", column: "code" } });
  expect(out).toContain("Ref: employees.is_active > divisions.code");
  expect(out.trimEnd().endsWith("Ref: employees.is_active > divisions.code")).toBe(true);
  expect(out).toContain("// TechnoDay schema");
  expect(parseDbml(out).tables).toHaveLength(parseDbml(SOURCE).tables.length);
});

test("drawing a relation handled by a standalone Ref rewrites that line in place", () => {
  const out = setColumnRef(SOURCE, { from: { table: "employees", column: "id" }, to: { table: "divisions", column: "code" } });
  expect(out).toContain("Ref: employees.id > divisions.code");
  expect(out).not.toContain("Ref: employees.id > nominations_current.id");
  expect(out.match(/Ref:/g)!.length).toBe(1);
});

test("adding a table inserts a block before the refs and keeps the rest", () => {
  const out = addTableToDbml(SOURCE, {
    name: "audit_log",
    columns: [
      { name: "id", type: "uuid", isPk: true, isUnique: false, isNotNull: false, defaultValue: null, ref: null },
      { name: "actor", type: "varchar(100)", isPk: false, isUnique: false, isNotNull: true, defaultValue: null, ref: null },
    ],
    indexes: [],
  });
  const parsed = parseDbml(out);
  expect(parsed.tables.map((t) => t.name)).toContain("audit_log");
  const audit = parsed.tables.find((t) => t.name === "audit_log")!;
  expect(audit.columns.map((c) => `${c.name}:${c.type}`)).toEqual(["id:uuid", "actor:varchar(100)"]);
  expect(audit.columns[0].isPk).toBe(true);
  // The new block sits above `Ref:`, so the ref still parses as a top-level statement.
  expect(out.indexOf("Table audit_log")).toBeLessThan(out.indexOf("Ref: employees.id"));
  expect(out).toContain("// TechnoDay schema");
});

test("removing a table drops its block, its refs, inline refs to it and its note", () => {
  const withNote = `${SOURCE}Note divisions: 'Master divisi'
`;
  const out = removeTableFromDbml(withNote, "divisions");
  const parsed = parseDbml(out);
  expect(parsed.tables.map((t) => t.name)).not.toContain("divisions");
  // The inline `ref: > divisions.id` on employees must be gone too.
  const employees = parsed.tables.find((t) => t.name === "employees")!;
  expect(employees.columns.find((c) => c.name === "division_id")!.ref).toBeNull();
  expect(out).not.toContain("Note divisions");
  // Everything unrelated survives.
  expect(out).toContain("// TechnoDay schema");
  expect(out).toContain("Ref: employees.id > nominations_current.id");
  expect(out).toContain('created_at [name: "idx_nominations_created_at"]');
});

test("a table edit rewrites only the changed column and keeps the others raw", () => {
  const prev = parseDbml(SOURCE).tables.find((t) => t.name === "employees")!;
  const next = {
    ...prev,
    columns: prev.columns.map((c) => (c.name === "division_id" ? { ...c, type: "bigint" } : c)),
  };
  const out = updateTableInDbml(SOURCE, prev, next);
  const parsed = parseDbml(out).tables.find((t) => t.name === "employees")!;
  expect(parsed.columns.find((c) => c.name === "division_id")!.type).toBe("bigint");
  // The untouched lines are byte-identical, comment included.
  expect(out).toContain("// someone's note about a column");
  expect(out).toContain("is_active boolean [default: true]");
  expect(out).toContain('nama_pengirim varchar(100) [not null, note: "Check char_length <= 100"]');
  expect(out).toContain("// TechnoDay schema");
});

test("adding and removing a column keeps multi-line settings intact", () => {
  const multiline = `Table orders {
  id uuid [pk]
  total numeric [
    not null,
    default: 0,
    note: 'grand total'
  ]
}
`;
  const prev = parseDbml(multiline).tables[0];
  const withColumn = {
    ...prev,
    columns: [
      ...prev.columns,
      { name: "created_at", type: "timestamptz", isPk: false, isUnique: false, isNotNull: false, defaultValue: null, ref: null },
    ],
  };
  const added = updateTableInDbml(multiline, prev, withColumn);
  expect(parseDbml(added).tables[0].columns.map((c) => c.name)).toEqual(["id", "total", "created_at"]);
  expect(added).toContain("default: 0");

  const removedPrev = parseDbml(multiline).tables[0];
  const removed = updateTableInDbml(multiline, removedPrev, {
    ...removedPrev,
    columns: removedPrev.columns.filter((c) => c.name !== "total"),
  });
  expect(parseDbml(removed).tables[0].columns.map((c) => c.name)).toEqual(["id"]);
  expect(removed).not.toContain("grand total");
});

test("a rename rewrites that column in place instead of moving it to the end", () => {
  const prev = parseDbml(SOURCE).tables.find((t) => t.name === "employees")!;
  const next = {
    ...prev,
    columns: prev.columns.map((c) => (c.name === "division_id" ? { ...c, name: "div_id" } : c)),
  };
  const out = updateTableInDbml(SOURCE, prev, next);
  const parsed = parseDbml(out).tables.find((t) => t.name === "employees")!;
  expect(parsed.columns.map((c) => c.name)).toEqual(["id", "div_id", "is_active"]);
});

test("a new table block is separated from the previous one by a blank line", () => {
  const out = addTableToDbml(SOURCE, {
    name: "audit_log",
    columns: [{ name: "id", type: "uuid", isPk: true, isUnique: false, isNotNull: false, defaultValue: null, ref: null }],
    indexes: [],
  });
  expect(out).toContain("}\n\nTable audit_log {");
});

test("editing a column that relates through a standalone Ref does not duplicate the relation", () => {
  const source = `Table users {
  id uuid [pk]
}
Table orders {
  id uuid [pk]
  total numeric [not null, default: 0]
}
Ref: orders.total > users.id
`;
  const prev = parseDbml(source).tables.find((t) => t.name === "orders")!;
  const next = { ...prev, columns: prev.columns.map((c) => (c.name === "total" ? { ...c, type: "numeric(12,2)" } : c)) };
  const out = updateTableInDbml(source, prev, next);
  // One statement of the relation, still in the file's own style.
  expect(out.match(/ref\s*:/gi)!.length).toBe(1);
  expect(out).toContain("Ref: orders.total > users.id");
  expect(out).toContain("total numeric(12,2) [not null, default: 0]");
});

test("changing a column's relation through the panel writes an inline ref", () => {
  const source = `Table users {
  id uuid [pk]
}
Table orders {
  id uuid [pk]
  user_id uuid
}
`;
  const prev = parseDbml(source).tables.find((t) => t.name === "orders")!;
  const next = {
    ...prev,
    columns: prev.columns.map((c) => (c.name === "user_id" ? { ...c, ref: { table: "users", column: "id", relation: ">" } } : c)),
  };
  const out = updateTableInDbml(source, prev, next);
  expect(out).toContain("user_id uuid [ref: > users.id]");
});
